#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)";cd "$ROOT";export JAVA_HOME="${JAVA_HOME:-${JAVA_HOME_17_X64:-}}";: "${ZUNGUN_PILOT_TOKEN:?required}"
OUT="${ORDER083_FIELD_RECOVERY_EVIDENCE:-$ROOT/evidence/order083/field-recovery}";mkdir -p "$OUT";GRADLE=(android/gradle/bootstrap-gradle.sh -p android --no-daemon --stacktrace);"${GRADLE[@]}" :app:assembleDebug :app:assembleDebugAndroidTest
adb install -r android/app/build/outputs/apk/debug/app-debug.apk >/dev/null;adb install -r android/app/build/outputs/apk/androidTest/debug/app-debug-androidTest.apk >/dev/null;RUNNER='com.zungun.app.test/androidx.test.runner.AndroidJUnitRunner'
run(){ adb shell am instrument -w -r -e class "com.zungun.app.Order083FieldRecoveryInstrumentedTest#$1" "$RUNNER" | tee "$OUT/$1.log";grep -q 'OK (1 test)' "$OUT/$1.log"; }
connectivity_snapshot(){ timeout 5s adb shell dumpsys connectivity 2>/dev/null; }
snapshot_online(){ grep -Eq 'Capabilities:.*INTERNET.*VALIDATED|Capabilities:.*VALIDATED.*INTERNET' <<<"$1"; }
assert_online(){ local label="$1" state;state="$(connectivity_snapshot)" || { echo "CONNECTIVITY_PROBE_COMMAND_FAILED:$label" >&2;return 2; };printf '%s\n' "$state" > "$OUT/connectivity-$label.txt";snapshot_online "$state" || { echo "CONNECTIVITY_NOT_VALIDATED:$label" >&2;return 1; }; }
prepare_outage_control(){ local root_output;root_output="$(adb root 2>&1 || true)";printf '%s\n' "$root_output" > "$OUT/adb-root.txt";grep -qi 'cannot run as root' "$OUT/adb-root.txt" && { echo 'ADB_ROOT_REQUIRED_FOR_DETERMINISTIC_OUTAGE' >&2;return 1; };timeout 30s adb wait-for-device;test "$(adb shell id -u 2>/dev/null|tr -d '\r')" = 0 || { echo 'ADB_ROOT_NOT_ACTIVE' >&2;return 1; };NET_IF="$(adb shell ip route show default 2>/dev/null|tr -d '\r'|awk 'NR==1{for(i=1;i<=NF;i++)if($i=="dev"){print $(i+1);exit}}')";test -n "$NET_IF" || { echo 'DEFAULT_NETWORK_INTERFACE_NOT_FOUND' >&2;return 1; };printf '%s\n' "$NET_IF" > "$OUT/default-network-interface.txt"; }
restore_network(){ if [[ -n "${NET_IF:-}" ]];then timeout 5s adb shell ip link set dev "$NET_IF" up >/dev/null 2>&1||true;fi; }
wait_offline(){ local label="$1" state;for _ in $(seq 1 30);do state="$(connectivity_snapshot)" || { echo "CONNECTIVITY_PROBE_COMMAND_FAILED:$label" >&2;return 2; };if ! snapshot_online "$state";then printf '%s\n' "$state" > "$OUT/connectivity-$label-offline.txt";return 0;fi;sleep 1;done;printf '%s\n' "$state" > "$OUT/connectivity-$label-timeout.txt";echo "CONNECTIVITY_OFFLINE_TIMEOUT:$label" >&2;return 1; }
off(){ local label="$1";timeout 5s adb shell ip link set dev "$NET_IF" down;wait_offline "$label";local state;state="$(connectivity_snapshot)";snapshot_online "$state" && { echo "CONNECTIVITY_OFFLINE_POST_ASSERTION_FAILED:$label" >&2;return 1; };printf '%s\n' "$state" > "$OUT/connectivity-$label-post.txt"; }
on(){ local label="$1" state recovered=0;timeout 5s adb shell ip link set dev "$NET_IF" up;for _ in $(seq 1 45);do state="$(connectivity_snapshot)" || { echo "CONNECTIVITY_PROBE_COMMAND_FAILED:$label" >&2;return 2; };if snapshot_online "$state";then recovered=1;printf '%s\n' "$state" > "$OUT/connectivity-$label-recovered.txt";break;fi;sleep 1;done;[[ "$recovered" == 1 ]] || { printf '%s\n' "$state" > "$OUT/connectivity-$label-timeout.txt";echo "CONNECTIVITY_RECOVERY_TIMEOUT:$label" >&2;return 1; };assert_online "$label-post"; }
prepare_outage_control;trap restore_network EXIT INT TERM
run phase1SetupOnline;assert_online baseline-b;off offline-b;run phase2QueueOffline;adb shell am force-stop com.zungun.app;on online-b;adb shell monkey -p com.zungun.app -c android.intent.category.LAUNCHER 1 >/dev/null;sleep 2;run phase3VerifyRecovered
run phase4SetupAmbiguousOnline;assert_online baseline-c;off offline-c;run phase5QueueAmbiguousOffline;OP="$(adb shell run-as com.zungun.app cat files/order083-ambiguous-operation-id.txt | tr -d '\r\n')";test -n "$OP";node tools/order083/set-pilot-fault.mjs "$OP" | tee "$OUT/fault.json";adb shell am force-stop com.zungun.app;on online-c;adb shell monkey -p com.zungun.app -c android.intent.category.LAUNCHER 1 >/dev/null;sleep 2;run phase6VerifyUnknownThenReconciled
trap - EXIT INT TERM;restore_network
printf '{"ok":true,"fieldOfflineForceStopRecovery":true,"ambiguousUnknownObserved":true,"reconcileBeforeRetry":true,"duplicateEffect":0,"connectivityProbe":"ANDROID_VALIDATED_NETWORK","connectivityProbeTimeoutSeconds":5,"outageControl":"EMULATOR_DEFAULT_INTERFACE_LINK","outageRequiresAdbRoot":true,"offlineAssertion":true,"postLoopConnectivityAssertion":true}\n' > "$OUT/result.json"
